import * as React from "react";
import { Button } from "./button";
import { Card, CardTitle, CardDescription } from "./card";
import { Accordion, NavigationMenu } from "./navigation";
import { Input, Field } from "./forms";
export function HeaderBlock({
  name,
  links,
  action,
}: {
  name: string;
  links: { label: string; href: string }[];
  action?: React.ReactNode;
}) {
  return (
    <header className="flex flex-wrap items-center justify-between gap-4 border-b border-line py-5">
      <a href="#top" className="font-editorial text-2xl">
        {name}
      </a>
      <NavigationMenu items={links} />
      {action}
    </header>
  );
}
export function HeroBlock({
  eyebrow,
  title,
  description,
  action,
}: {
  eyebrow: string;
  title: string;
  description: string;
  action?: React.ReactNode;
}) {
  return (
    <section className="grid items-center gap-8 py-16 md:grid-cols-[1.2fr_1fr]">
      <div>
        <p className="mb-6 text-xs uppercase tracking-widest text-muted">
          {eyebrow}
        </p>
        <h1 className="font-editorial text-4xl leading-tight tracking-tight md:text-5xl">
          {title}
        </h1>
      </div>
      <div>
        <p className="text-lg leading-relaxed text-muted">{description}</p>
        {action && <div className="mt-6">{action}</div>}
      </div>
    </section>
  );
}
export function EditorialBlock({
  label,
  title,
  children,
}: {
  label: string;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <section className="grid gap-8 border-t border-line py-12 md:grid-cols-2">
      <div>
        <p className="text-xs uppercase tracking-widest text-muted">{label}</p>
        <h2 className="mt-5 font-editorial text-3xl">{title}</h2>
      </div>
      <div className="space-y-4 leading-relaxed text-muted">{children}</div>
    </section>
  );
}
export function FeatureGrid({
  items,
}: {
  items: { title: string; description: string }[];
}) {
  return (
    <div className="grid gap-4 md:grid-cols-3">
      {items.map((i) => (
        <Card key={i.title}>
          <CardTitle>{i.title}</CardTitle>
          <CardDescription className="mt-4">{i.description}</CardDescription>
        </Card>
      ))}
    </div>
  );
}
export function FAQBlock({
  title,
  items,
}: {
  title: string;
  items: { title: string; content: React.ReactNode }[];
}) {
  return (
    <section className="py-12">
      <h2 className="mb-6 font-editorial text-3xl">{title}</h2>
      <Accordion items={items} />
    </section>
  );
}
export function CTABlock({
  title,
  children,
  action,
}: {
  title: string;
  children: React.ReactNode;
  action: React.ReactNode;
}) {
  return (
    <section className="rounded-2xl bg-surface p-8 md:p-12">
      <h2 className="font-editorial text-3xl">{title}</h2>
      <div className="my-4 max-w-xl text-muted">{children}</div>
      {action}
    </section>
  );
}
export function FooterBlock({
  name,
  links,
}: {
  name: string;
  links: { label: string; href: string }[];
}) {
  return (
    <footer className="mt-12 flex flex-wrap justify-between gap-6 border-t border-line py-8">
      <span className="font-editorial text-xl">{name}</span>
      <NavigationMenu items={links} />
    </footer>
  );
}
export function FormBlock({
  onSubmit,
}: {
  onSubmit: (data: { name: string; email: string }) => void;
}) {
  return (
    <form
      className="w-full min-w-0 space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        const d = new FormData(e.currentTarget);
        onSubmit({
          name: String(d.get("name")),
          email: String(d.get("email")),
        });
      }}
    >
      <Field label="Your name">
        <Input name="name" autoComplete="name" required />
      </Field>
      <Field label="Email" hint="Used only for this example.">
        <Input type="email" name="email" autoComplete="email" required />
      </Field>
      <div className="flex justify-end border-t border-line pt-5">
        <Button type="submit" className="w-full sm:w-auto">Continue</Button>
      </div>
    </form>
  );
}

export function LoginBlock({onSubmit}:{onSubmit:(data:{email:string;password:string})=>Promise<void>|void}){
 const [busy,setBusy]=React.useState(false),[error,setError]=React.useState('');
 return <div className="mx-auto w-full max-w-sm py-8"><div className="mb-7"><p className="font-editorial text-3xl tracking-tight">Welcome back.</p><p className="mt-3 text-sm text-muted">A familiar place to pick up where you left off.</p></div><form className="space-y-5" onSubmit={async e=>{e.preventDefault();const form=new FormData(e.currentTarget);setBusy(true);setError('');try{await onSubmit({email:String(form.get('email')),password:String(form.get('password'))})}catch{setError('Sign in could not be completed. Please try again.')}finally{setBusy(false)}}}><Field label="Email"><Input type="email" name="email" autoComplete="username" required placeholder="you@example.com"/></Field><Field label="Password" error={error||undefined}><Input name="password" type="password" autoComplete="current-password" required minLength={8}/></Field><Button className="w-full" type="submit" loading={busy}>Sign in</Button></form><p className="mt-6 text-center text-xs text-muted">Your work, right where you left it.</p></div>
}
export function SignupBlock({onSubmit}:{onSubmit:(data:{name:string;email:string;password:string})=>Promise<void>|void}){
 const [busy,setBusy]=React.useState(false),[error,setError]=React.useState('');
 return <div className="mx-auto w-full max-w-sm py-8"><div className="mb-7"><p className="font-editorial text-3xl tracking-tight">A new beginning.</p><p className="mt-3 text-sm text-muted">Make a little space for your next idea.</p></div><form className="space-y-5" onSubmit={async e=>{e.preventDefault();const d=new FormData(e.currentTarget);setBusy(true);setError('');try{await onSubmit({name:String(d.get('name')),email:String(d.get('email')),password:String(d.get('password'))})}catch{setError('We could not complete this step. Please try again.')}finally{setBusy(false)}}}><Field label="Your name"><Input name="name" autoComplete="name" required/></Field><Field label="Email"><Input name="email" type="email" autoComplete="email" required placeholder="you@example.com"/></Field><Field label="Password" hint="Use at least eight characters." error={error||undefined}><Input name="password" type="password" autoComplete="new-password" required minLength={8}/></Field><Button type="submit" className="w-full" loading={busy}>Create account</Button></form></div>
}
export function ApplicationShell({name,items,active,onNavigate,action,children}:{name:string;items:string[];active:string;onNavigate:(name:string)=>void;action?:React.ReactNode;children:React.ReactNode}){const [expanded,setExpanded]=React.useState(true);return <div className="flex min-h-[420px] overflow-hidden rounded-xl border border-line bg-paper"><aside className={(expanded?'w-48':'w-16')+' shrink-0 border-e border-line bg-card p-3 transition-[width] motion-reduce:transition-none'}><Button size="sm" tone="quiet" aria-label={expanded?'Collapse sidebar':'Expand sidebar'} onClick={()=>setExpanded(!expanded)}>{expanded?name:name.slice(0,1)}</Button><nav aria-label="Workspace" className="mt-6 space-y-1">{items.map(i=><button key={i} title={expanded?undefined:i} onClick={()=>onNavigate(i)} aria-current={active===i?'page':undefined} className={'block w-full overflow-hidden rounded-md px-3 py-2 text-start text-xs '+(active===i?'bg-surface text-ink':'text-muted hover:bg-surface')}>{expanded?i:i.slice(0,1)}</button>)}</nav></aside><div className="min-w-0 flex-1"><header className="flex min-h-16 items-center justify-between border-b border-line px-5"><h2 className="text-sm font-medium">{active}</h2>{action}</header><div className="p-5">{children}</div></div></div>}

import * as React from "react";
import { LoaderCircle } from "lucide-react";
import { cx } from "./utils";

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  tone?: "primary" | "secondary" | "outline" | "quiet" | "danger" | "accent";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
};

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  function Button(
    {
      tone = "primary",
      size = "md",
      loading = false,
      disabled,
      children,
      className,
      type = "button",
      ...props
    },
    ref,
  ) {
    return (
      <button
        {...props}
        ref={ref}
        type={type}
        disabled={disabled || loading}
        aria-busy={loading ? true : props["aria-busy"]}
        className={cx(
          "a-button relative",
          {
            "bg-ink text-paper hover:bg-ink/85": tone === "primary",
            "bg-surface text-ink hover:bg-surface/70": tone === "secondary",
            "border border-control bg-transparent text-ink": tone === "outline",
            "bg-transparent text-ink hover:bg-surface": tone === "quiet",
            "bg-danger text-on-danger": tone === "danger",
            "bg-gold text-[#181818]": tone === "accent",
          },
          {
            "min-h-11 sm:min-h-9 px-3 py-2 text-xs": size === "sm",
            "min-h-11 px-4 py-2 text-sm": size === "md",
            "min-h-13 px-6 py-3 text-base": size === "lg",
          },
          loading && "disabled:opacity-100",
          className,
        )}
      >
        <span
          className="inline-flex min-w-0 items-center justify-center gap-2 [&_svg]:shrink-0"
          style={{ opacity: loading ? 0 : undefined }}
        >
          {children}
        </span>
        {loading && (
          <span
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 flex items-center justify-center"
          >
            <LoaderCircle className="size-4 animate-spin motion-reduce:animate-none" />
          </span>
        )}
      </button>
    );
  },
);

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export const cx = (...values: ClassValue[]) => twMerge(clsx(values));

import * as React from "react";
import { cx } from "./utils";

export function Card({
  className,
  ...props
}: React.HTMLAttributes<HTMLElement>) {
  return (
    <article
      className={cx("a-card rounded-xl bg-card", className)}
      {...props}
    />
  );
}

export function CardHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("mb-5 space-y-2", className)} {...props} />;
}

export function CardTitle({
  className,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h3
      className={cx("text-xl font-medium tracking-tight", className)}
      {...props}
    />
  );
}

export function CardDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cx("text-sm leading-relaxed text-muted", className)}
      {...props}
    />
  );
}

export function CardFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cx("mt-6 flex flex-wrap items-center gap-3", className)}
      {...props}
    />
  );
}

import * as React from "react";
import {
  Tabs as TB,
  Accordion as AC,
  Collapsible as CO,
  DropdownMenu as DM,
  ContextMenu as CM,
  Menubar as MB,
  NavigationMenu as NM,
  ScrollArea as SA,
} from "radix-ui";
import { Search, Menu, ChevronRight } from "lucide-react";
import { Button } from "./button";
import { Modal } from "./overlays";
import { ScrollFade, useScrollFade } from "./scroll-fade";
export function Tabs({
  items,
  defaultValue,
}: {
  items: { value: string; label: string; content: React.ReactNode }[];
  defaultValue?: string;
}) {
  return (
    <TB.Root defaultValue={defaultValue || items[0]?.value}>
      <TB.List
        aria-label="Sections"
        className="mb-5 flex flex-wrap gap-1 rounded-lg bg-surface p-1"
      >
        {items.map((i) => (
          <TB.Trigger
            key={i.value}
            value={i.value}
            className="rounded-md px-4 py-2 text-sm data-[state=active]:bg-card"
          >
            {i.label}
          </TB.Trigger>
        ))}
      </TB.List>
      {items.map((i) => (
        <TB.Content key={i.value} value={i.value} className="a-tabs-content">
          {i.content}
        </TB.Content>
      ))}
    </TB.Root>
  );
}
export function Accordion({
  items,
}: {
  items: { title: string; content: React.ReactNode }[];
}) {
  return (
    <AC.Root type="single" collapsible>
      {items.map((i, n) => (
        <AC.Item key={n} value={String(n)} className="border-b border-line">
          <AC.Header>
            <AC.Trigger className="a-accordion-trigger flex w-full items-center justify-between gap-3 py-5 text-start text-sm font-medium">
              {i.title}
              <ChevronRight className="size-4 shrink-0" />
            </AC.Trigger>
          </AC.Header>
          <AC.Content className="a-accordion-content text-sm leading-relaxed text-muted">
            <div className="pb-5">{i.content}</div>
          </AC.Content>
        </AC.Item>
      ))}
    </AC.Root>
  );
}
export function Collapsible({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}) {
  return (
    <CO.Root>
      <CO.Trigger asChild>
        <Button tone="outline">{title}</Button>
      </CO.Trigger>
      <CO.Content className="a-collapsible mt-4 rounded-lg bg-surface p-4 text-sm">
        {children}
      </CO.Content>
    </CO.Root>
  );
}
export type MenuOption = {
  label: string;
  onSelect: () => void;
  disabled?: boolean;
  danger?: boolean;
};
const menuClass =
  "cursor-pointer rounded-md px-3 py-2 text-sm outline-none data-[highlighted]:bg-surface data-[disabled]:opacity-40";
export function DropdownMenu({
  trigger,
  items,
}: {
  trigger: React.ReactElement;
  items: MenuOption[];
}) {
  return (
    <DM.Root>
      <DM.Trigger asChild>{trigger}</DM.Trigger>
      <DM.Portal>
        <DM.Content className="a-popup min-w-44" sideOffset={6}>
          {items.map((i) => (
            <DM.Item
              key={i.label}
              disabled={i.disabled}
              onSelect={i.onSelect}
              className={menuClass + (i.danger ? " text-danger" : "")}
            >
              {i.label}
            </DM.Item>
          ))}
        </DM.Content>
      </DM.Portal>
    </DM.Root>
  );
}
export function ContextMenu({
  children,
  items,
}: {
  children: React.ReactNode;
  items: MenuOption[];
}) {
  return (
    <CM.Root>
      <CM.Trigger className="block">{children}</CM.Trigger>
      <CM.Portal>
        <CM.Content className="a-popup min-w-44">
          {items.map((i) => (
            <CM.Item
              key={i.label}
              disabled={i.disabled}
              onSelect={i.onSelect}
              className={menuClass}
            >
              {i.label}
            </CM.Item>
          ))}
        </CM.Content>
      </CM.Portal>
    </CM.Root>
  );
}
export function Menubar({
  menus,
}: {
  menus: { label: string; items: MenuOption[] }[];
}) {
  return (
    <MB.Root className="flex rounded-lg border border-line p-1">
      {menus.map((m) => (
        <MB.Menu key={m.label}>
          <MB.Trigger className="rounded px-3 py-2 text-sm data-[state=open]:bg-surface">
            {m.label}
          </MB.Trigger>
          <MB.Portal>
            <MB.Content className="a-popup min-w-44">
              {m.items.map((i) => (
                <MB.Item
                  key={i.label}
                  disabled={i.disabled}
                  onSelect={i.onSelect}
                  className={menuClass}
                >
                  {i.label}
                </MB.Item>
              ))}
            </MB.Content>
          </MB.Portal>
        </MB.Menu>
      ))}
    </MB.Root>
  );
}
export function NavigationMenu({
  items,
}: {
  items: { label: string; href: string }[];
}) {
  return (
    <NM.Root aria-label="Main navigation">
      <NM.List className="flex flex-wrap gap-5">
        {items.map((i) => (
          <NM.Item key={i.href}>
            <NM.Link
              href={i.href}
              className="text-sm underline-offset-4 hover:underline"
            >
              {i.label}
            </NM.Link>
          </NM.Item>
        ))}
      </NM.List>
    </NM.Root>
  );
}
export function Breadcrumb({
  items,
}: {
  items: { label: string; href?: string }[];
}) {
  return (
    <nav aria-label="Breadcrumb">
      <ol className="flex flex-wrap items-center gap-2 text-sm">
        {items.map((i, n) => (
          <li key={n} className="flex items-center gap-2">
            {n > 0 && (
              <ChevronRight aria-hidden className="size-3 text-muted" />
            )}
            {i.href ? (
              <a href={i.href} className="text-muted hover:underline">
                {i.label}
              </a>
            ) : (
              <span aria-current="page">{i.label}</span>
            )}
          </li>
        ))}
      </ol>
    </nav>
  );
}
export function Pagination({
  page,
  total,
  onChange,
}: {
  page: number;
  total: number;
  onChange: (p: number) => void;
}) {
  return (
    <nav aria-label="Pagination" className="flex items-center gap-3">
      <Button
        tone="outline"
        size="sm"
        disabled={page <= 1}
        onClick={() => onChange(page - 1)}
      >
        Previous
      </Button>
      <span className="text-sm" aria-live="polite">
        Page {page} of {total}
      </span>
      <Button
        tone="outline"
        size="sm"
        disabled={page >= total}
        onClick={() => onChange(page + 1)}
      >
        Next
      </Button>
    </nav>
  );
}
export function ScrollArea({
  children,
  className = "h-44",
  label = "Scrollable content",
  fade = false,
}: {
  children: React.ReactNode;
  className?: string;
  label?: string;
  fade?: boolean;
}) {
  const { ref, edges } = useScrollFade({ enabled: fade });
  return (
    <SA.Root type="auto" data-fade-top={edges.top} data-fade-bottom={edges.bottom} className={"a-scroll-area relative overflow-hidden " + className}>
      <SA.Viewport ref={ref} role="region" aria-label={label} tabIndex={0} className="size-full rounded-[inherit] focus-visible:outline-offset-[-2px]">
        {children}
      </SA.Viewport>
      <ScrollFade edges={edges} depth="min(48px, 12%)" style={{ insetInlineEnd: 14 }} />
      <SA.Scrollbar orientation="vertical" className="a-scroll-track">
        <SA.Thumb className="a-scroll-thumb" />
      </SA.Scrollbar>
    </SA.Root>
  );
}
export function Sidebar({
  items,
  children,
}: {
  items: { label: string; href: string }[];
  children: React.ReactNode;
}) {
  return (
    <div className="grid min-h-60 gap-6 sm:grid-cols-[160px_1fr]">
      <aside className="border-b border-line pb-4 sm:border-b-0 sm:border-e sm:pe-4">
        <NavigationMenu items={items} />
      </aside>
      <div>{children}</div>
    </div>
  );
}
export function Command({
  items,
}: {
  items: { label: string; onSelect: () => void }[];
}) {
  const [open, setOpen] = React.useState(false),
    [q, setQ] = React.useState("");
  const input = React.useRef<HTMLInputElement>(null);
  const [active, setActive] = React.useState(0);
  const filtered = items.filter((i) =>
    i.label.toLowerCase().includes(q.toLowerCase()),
  );
  return (
    <Modal
      open={open}
      onOpenChange={setOpen}
      trigger={
        <Button tone="outline">
          <Search className="size-4" />
          Search commands
        </Button>
      }
      title="Commands"
      description="Search and run a command."
    >
      <input
        ref={input}
        value={q}
        onChange={(e) => {
          setQ(e.target.value);
          setActive(0);
        }}
        aria-label="Search commands"
        role="combobox"
        aria-expanded="true"
        aria-controls="a-command-list"
        aria-activedescendant={
          filtered.length ? "a-command-" + active : undefined
        }
        className="a-input"
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") {
            e.preventDefault();
            setActive((i) => Math.min(i + 1, filtered.length - 1));
          }
          if (e.key === "ArrowUp") {
            e.preventDefault();
            setActive((i) => Math.max(i - 1, 0));
          }
          if (e.key === "Enter" && filtered[active]) {
            filtered[active].onSelect();
            setOpen(false);
          }
        }}
      />
      <ul
        id="a-command-list"
        role="listbox"
        aria-label="Commands"
        className="mt-3"
      >
        {filtered.map((i, n) => (
          <li
            role="option"
            aria-selected={n === active}
            id={"a-command-" + n}
            key={i.label}
            className={
              "cursor-pointer rounded p-3 text-sm " +
              (n === active ? "bg-surface" : "")
            }
            onClick={() => {
              i.onSelect();
              setOpen(false);
            }}
          >
            {i.label}
          </li>
        ))}
      </ul>
      {!filtered.length && (
        <p role="status" className="p-3 text-sm text-muted">
          No commands found.
        </p>
      )}
    </Modal>
  );
}

import * as React from "react";
import {
  Dialog as D,
  AlertDialog as A,
  Popover as P,
  Tooltip as T,
  HoverCard as H,
  Toast as RT,
} from "radix-ui";
import { X } from "lucide-react";
import { Button } from "./button";
import { cx } from "./utils";
type ModalProps = {
  trigger?: React.ReactElement;
  title: string;
  description: string;
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (v: boolean) => void;
  footer?: React.ReactNode;
  placement?: "center" | "right" | "bottom";
};
export function Modal({
  trigger,
  title,
  description,
  children,
  open,
  onOpenChange,
  footer,
  placement = "center",
}: ModalProps) {
  const previousFocus = React.useRef<HTMLElement | null>(null);
  return (
    <D.Root open={open} onOpenChange={onOpenChange}>
      {trigger && <D.Trigger asChild>{trigger}</D.Trigger>}
      <D.Portal>
        <D.Overlay className="a-overlay" />
        <D.Content
          onOpenAutoFocus={() => {
            previousFocus.current = document.activeElement instanceof HTMLElement
              ? document.activeElement
              : null;
          }}
          onCloseAutoFocus={(event) => {
            if (!trigger && previousFocus.current?.isConnected) {
              event.preventDefault();
              previousFocus.current.focus({ preventScroll: true });
            }
          }}
          className={cx(
            "a-modal-content fixed z-50 flex max-h-[90dvh] flex-col border border-line bg-card text-ink shadow-xl outline-none",
            placement === "center"
              ? "left-1/2 top-1/2 w-[min(560px,calc(100%-32px))] -translate-x-1/2 -translate-y-1/2 rounded-2xl"
              : placement === "right"
                ? "right-0 top-0 h-dvh max-h-dvh w-[min(460px,100%)]"
                : "bottom-0 left-1/2 w-full max-w-3xl -translate-x-1/2 max-h-[85dvh] rounded-t-2xl",
          )}
        >
