@media (prefers-reduced-motion: reduce) {
  .a-edge-fade::after,
  .a-surface-lift {
    transition: none;
  }
  .a-surface-lift:hover {
    translate: none;
  }
}
@media (forced-colors: active) {
  .a-edge-fade::after {
    display: none;
  }
}
